{
  "exchange": {
    "name": "binance",
    "key": "YOUR_KEY",
    "secret": "YOUR_SECRET",

    // ccxt 通用配置（同时作用于同步/异步实例）
    "ccxt_config": {
      "enableRateLimit": true,          // 强烈建议：内置限流
      "timeout": 30000                  // 30s 超时（按需调整）
    },

    // 仅作用于同步实例（下单/REST 轮询）
    "ccxt_sync_config": {
      "enableRateLimit": true
    },

    // 仅作用于异步实例（WS/并发拉取等）
    "ccxt_async_config": {
      "enableRateLimit": true,
      "rateLimit": 500                  // 例：每 500ms 1 次；具体值看交易所规则
    },

    // WebSocket（Freqtrade 用 ccxt.pro 接入，默认启用）
    "enable_ws": true
  }
}
